import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:yosemite_survival/geo/map_pack.dart';

// Port of PR #5's MapPackTest.kt: the Dart map pack must answer exactly like the Python
// pipeline (test/fixtures/parity.json, regenerated by tool/geopdf/scripts/build_android_assets.py).
void main() {
  final pack = MapPack.parse(File('assets/park_map/mappack.json').readAsStringSync());
  final parity = jsonDecode(File('test/fixtures/parity.json').readAsStringSync()) as Map<String, dynamic>;

  test('search matches python for every place on the map', () {
    final failures = <String>[];
    final searches = parity['searches'] as List;
    for (final c in searches) {
      final hits = pack.search(c['query'] as String);
      final lat = (c['lat'] as num).toDouble(), lon = (c['lon'] as num).toDouble();
      final hit = hits.isEmpty ? null : hits.first;
      if (hit == null || (hit.place.location.latitude - lat).abs() > 1e-5 || (hit.place.location.longitude - lon).abs() > 1e-5) {
        failures.add('${c['query']}: python ${c['label']} ($lat, $lon), dart ${hit?.place.text} ${hit?.place.location}');
      }
    }
    expect(failures, isEmpty, reason: '${failures.length}/${searches.length} differ');
  });

  test('gps guidance matches python', () {
    final failures = <String>[];
    final positions = parity['positions'] as List;
    for (final c in positions) {
      final expected = [
        for (final g in c['guidance'] as List) '${g['text']} | ${g['reason']}',
      ];
      final actual = [
        for (final a in pack.guidanceAt((c['lat'] as num).toDouble(), (c['lon'] as num).toDouble()))
          '${a.note.text} | ${a.reason}',
      ];
      if (expected.join('\n') != actual.join('\n')) failures.add('${c['lat']},${c['lon']}\n  python $expected\n  dart $actual');
    }
    expect(failures, isEmpty, reason: '${failures.length}/${positions.length} differ:\n${failures.take(3).join('\n')}');
  });

  test('page and lat lon round trip', () {
    for (final x in [0.0, 300.0, 1165.0]) {
      for (final y in [0.0, 600.0, 1233.0]) {
        final ll = pack.pageToLatLon(x, y);
        final (bx, by) = pack.latLonToPage(ll.latitude, ll.longitude);
        expect((bx - x).abs() < 1e-6 && (by - y).abs() < 1e-6, isTrue, reason: '($x, $y) -> ($bx, $by)');
      }
    }
  });

  test('half dome is at the summit', () {
    final best = pack.search('half dome').first;
    expect(best.place.text, 'Half Dome');
    expect(best.exact && best.place.snapped, isTrue);
    expect(best.place.location.latitude, closeTo(37.7459, 0.001));
    expect(best.place.location.longitude, closeTo(-119.5332, 0.001));
  });

  test('exact label ranks above road label', () {
    final hits = pack.search('Glacier Point');
    expect(hits.first.place.text, 'Glacier Point');
    expect(hits.skip(1).any((h) => h.place.text == 'Glacier Point Road'), isTrue);
  });

  test('tioga closures apply between the gates only', () {
    final olmsted = pack.guidanceFor(pack.search('Olmsted Point').first.place).map((a) => a.note.text);
    expect(olmsted.any((t) => t.startsWith('Tioga Road closed')), isTrue);
    final leeVining = pack.guidanceFor(pack.search('Lee Vining').first.place).map((a) => a.note.text);
    expect(leeVining.any((t) => t.startsWith('Tioga Road closed')), isFalse);
  });

  test('park wide notes', () {
    expect(pack.parkWide.length, 3);
    expect(pack.parkWide.any((n) => n.text.startsWith('Natural areas present hazards')), isTrue);
  });

  test('image covers the park', () {
    final (nw, se) = pack.imageBounds;
    expect(nw.latitude > se.latitude && nw.longitude < se.longitude, isTrue);
    expect(pack.isOnMap(37.7459, -119.5332), isTrue); // Half Dome
    expect(pack.isOnMap(46.8770, -121.7304), isFalse); // Mount Rainier
  });

  test('rejects other formats', () {
    final bad = File('assets/park_map/mappack.json').readAsStringSync().replaceFirst('"version":1', '"version":99');
    expect(() => MapPack.parse(bad), throwsArgumentError);
  });
}
